/** Native frame-project gallery, editing actions and validated JSON exchange. */
public final class DevGramFrameProjectsSheet {
    private static final int IMPORT=7686,EXPORT=7687;
    private final BaseFragment host;private final DevGramStudioActivity.Draft draft;private final long viewer;private final Theme.ResourcesProvider resources;
    private final ArrayList<DevGramStudioPreview> previews=new ArrayList<>();private final ArrayList<JSONObject> projects=new ArrayList<>();
    private boolean closed,busy,favoritesOnly;private int generation,next;private String query="";private byte[] exporting;private JSONObject archiveExport;private BottomSheet sheet;private LinearLayout gallery;private EditText search;
    private final Runnable searchLater=()->load(true);
    private final Runnable policy=()->{if(!valid()){generation++;busy=false;AndroidUtilities.cancelRunOnUIThread(searchLater);if(sheet!=null)sheet.dismiss();releasePreviews();}};
    public DevGramFrameProjectsSheet(BaseFragment host,DevGramStudioActivity.Draft draft,Theme.ResourcesProvider resources){this.host=host;this.draft=draft;this.resources=resources;viewer=host.getUserConfig().getClientUserId();DevGramProfilePolicy.listen(policy);}
    private String t(String value){return DevGramLocale.text(value);}private boolean valid(){return !closed&&DevGramProfileCustomization.enabled()&&host.getUserConfig().getClientUserId()==viewer&&DevGramProfilePolicy.allowed(viewer,"avatar.projects");}
    private boolean access(String feature){return valid()&&DevGramAppearanceAccess.check(host,feature,sheet!=null&&sheet.isShowing()?sheet.getContainer():null);}
    private void error(){if(valid()&&host.getParentActivity()!=null)BulletinFactory.of(host).createErrorBulletin(t("Не удалось выполнить действие. Проверьте доступ и соединение.")).show();}
    private void request(JSONObject fields,java.util.function.Consumer<JSONObject> callback){if(!valid()||busy)return;busy=true;int request=++generation;try{fields.put("limit",6).put("q",query).put("favoritesOnly",favoritesOnly);}catch(Exception ignored){}DevGramProfilePolicy.request(host.getCurrentAccount(),"studio/projects",fields,(result,error)->{if(closed||request!=generation)return;busy=false;if(!valid())return;if(result==null){error();return;}callback.accept(result);});}
    private JSONObject json(String action){try{return new JSONObject().put("action",action);}catch(Exception e){return new JSONObject();}}
    private static JSONObject frame(JSONObject document){JSONObject result=new JSONObject();try{result.put("v",1);for(String key:new String[]{"layers","nodes","frameGraph"})if(document!=null&&document.has(key))result.put(key,document.opt(key));}catch(Exception ignored){}return DevGramProfileDocument.copy(result);}
    public void show(){if(busy)return;if(!access("avatar.projects")||host.getParentActivity()==null)return;LinearLayout body=DevGramStudioControls.column(host.getParentActivity());search=new EditText(host.getParentActivity());search.setSingleLine(true);search.setTextColor(Theme.getColor(Theme.key_dialogTextBlack,resources));search.setHintTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,resources));search.setHint(t("Поиск проектов"));search.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(12),AndroidUtilities.dp(22),AndroidUtilities.dp(12));search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});search.setText(query);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString();AndroidUtilities.cancelRunOnUIThread(searchLater);AndroidUtilities.runOnUIThread(searchLater,300);}public void afterTextChanged(Editable e){}});body.addView(search);row(body,favoritesOnly?"Все проекты":"Избранные рамки",()->{favoritesOnly=!favoritesOnly;show();});row(body,"Сохранить текущую рамку",()->name("Название проекта","",title->save(0,title)));row(body,"Импортировать рамку",()->{if(access("profile.import"))pick(IMPORT,"*/*",null);});gallery=DevGramStudioControls.column(host.getParentActivity());body.addView(gallery);ScrollView scroll=new ScrollView(host.getParentActivity());scroll.addView(body);sheet=new BottomSheet.Builder(host.getParentActivity(),false,resources).setTitle(t(favoritesOnly?"Избранные рамки":"Мои проекты")).setCustomView(scroll).create();sheet.fixNavigationBarKey(Theme.key_dialogBackground);host.showDialog(sheet,d->{releasePreviews();gallery=null;search=null;sheet=null;});load(true);}
    private void load(boolean reset){if(!valid()||gallery==null)return;if(busy){AndroidUtilities.runOnUIThread(searchLater,150);return;}AndroidUtilities.cancelRunOnUIThread(searchLater);if(reset){next=0;projects.clear();render();}JSONObject fields=json("list");try{fields.put("offset",next);}catch(Exception ignored){}String requested=query;request(fields,result->{if(!requested.equals(query)){load(true);return;}JSONArray values=result.optJSONArray("projects");if(values!=null)for(int i=0;i<values.length();i++){JSONObject project=values.optJSONObject(i);if(project!=null)projects.add(project);}next=result.isNull("next")?-1:result.optInt("next",-1);render();});}
    private void render(){if(gallery==null||host.getParentActivity()==null)return;releasePreviews();gallery.removeAllViews();LinearLayout line=null;for(int i=0;i<projects.size();i++){JSONObject project=projects.get(i);if(i%2==0){line=new LinearLayout(host.getParentActivity());gallery.addView(line);}LinearLayout card=DevGramStudioControls.column(host.getParentActivity());card.setPadding(AndroidUtilities.dp(8),AndroidUtilities.dp(8),AndroidUtilities.dp(8),AndroidUtilities.dp(12));card.setBackground(DevGramStudioControls.surface(Theme.getColor(Theme.key_windowBackgroundGray,resources),0));DevGramStudioPreview preview=new DevGramStudioPreview(host.getParentActivity(),host.getCurrentAccount(),viewer);preview.setStill(true);preview.setFrameOnly(true);preview.set(frame(project.optJSONObject("document")),new DevGramProfileStyle.Style(new JSONObject()));previews.add(preview);card.addView(preview,new LinearLayout.LayoutParams(-1,AndroidUtilities.dp(132)));preview.setOnTouchListener((v,event)->{if(event.getAction()==MotionEvent.ACTION_UP){actions(project);v.performClick();}return true;});TextView title=DevGramStudioControls.text(host.getParentActivity(),project.optString("title"),14,true,resources);title.setGravity(Gravity.CENTER);title.setMaxLines(2);card.addView(title);TextView date=DevGramStudioControls.text(host.getParentActivity(),java.text.DateFormat.getDateInstance().format(new Date(project.optLong("updated")*1000)),11,false,resources);date.setGravity(Gravity.CENTER);date.setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteGrayText,resources));card.addView(date);card.setOnClickListener(v->actions(project));LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(0,-2,1);params.setMargins(AndroidUtilities.dp(5),AndroidUtilities.dp(5),AndroidUtilities.dp(5),AndroidUtilities.dp(5));line.addView(card,params);}if(line!=null&&projects.size()%2!=0)line.addView(new View(host.getParentActivity()),new LinearLayout.LayoutParams(0,1,1));if(projects.isEmpty()){TextView empty=DevGramStudioControls.text(host.getParentActivity(),busy?"Загружаю…":"Пока нет сохранённых проектов",14,false,resources);empty.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(18),AndroidUtilities.dp(22),AndroidUtilities.dp(18));gallery.addView(empty);}if(next>=0)row(gallery,"Загрузить ещё",()->load(false));}
    private void row(LinearLayout parent,String label,Runnable click){TextSettingsCell row=new TextSettingsCell(host.getParentActivity(),resources);row.setText(t(label),true);row.setOnClickListener(v->{if(valid()&&!busy)click.run();});parent.addView(row);}
    private void actions(JSONObject project){if(!valid()||busy)return;host.showDialog(new AlertDialog.Builder(host.getParentActivity(),resources).setTitle(project.optString("title")).setItems(new String[]{t("Открыть рамку"),t("Обновить текущей рамкой"),t("Переименовать"),t("Экспортировать рамку"),t("Сделать копию"),t("Удалить")},(d,which)->{if(!valid())return;if(which==0&&access("avatar.nodes")){apply(frame(project.optJSONObject("document")));}else if(which==1)host.showDialog(new AlertDialog.Builder(host.getParentActivity(),resources).setTitle(t("Заменить сохранённую рамку?")).setPositiveButton(t("Сохранить"),(dialog,w)->save(project.optLong("id"),project.optString("title"))).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).create());else if(which==2)name("Переименовать",project.optString("title"),title->{JSONObject fields=json("rename");try{fields.put("id",project.optLong("id")).put("title",title);}catch(Exception ignored){}request(fields,result->show());});else if(which==3)export(frame(project.optJSONObject("document")));else if(which==4){JSONObject fields=json("duplicate");try{fields.put("id",project.optLong("id")).put("title",project.optString("title").substring(0,Math.min(65,project.optString("title").length()))+" · "+t("Копия"));}catch(Exception ignored){}request(fields,result->show());}else if(which==5)host.showDialog(new AlertDialog.Builder(host.getParentActivity(),resources).setTitle(t("Удалить проект?")).setPositiveButton(t("Удалить"),(dialog,w)->{JSONObject fields=json("delete");try{fields.put("id",project.optLong("id"));}catch(Exception ignored){}request(fields,result->show());}).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).create());}).create());}
    private void name(String title,String initial,java.util.function.Consumer<String> done){EditText input=new EditText(host.getParentActivity());input.setSingleLine(true);input.setTextColor(Theme.getColor(Theme.key_dialogTextBlack,resources));input.setText(initial);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});input.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(12),AndroidUtilities.dp(22),AndroidUtilities.dp(12));host.showDialog(new AlertDialog.Builder(host.getParentActivity(),resources).setTitle(t(title)).setView(input).setPositiveButton(t("Сохранить"),(d,w)->{String value=input.getText().toString().trim();if(!value.isEmpty()&&valid())done.accept(value);}).setNegativeButton(DevGramLocale.getString(R.string.Cancel),null).create());}
    public void saveCurrent(){if(access("avatar.projects"))name("Название проекта","",title->save(0,title));}
    private void save(long id,String title){JSONObject fields=json("save");try{fields.put("id",id).put("title",title).put("document",frame(draft.document)).put("theme",new JSONObject());}catch(Exception ignored){}request(fields,result->{if(valid()&&host.getParentActivity()!=null)BulletinFactory.of(host).createSimpleBulletin(R.raw.contact_check,t("Проект сохранён")).show();});}
    private void apply(JSONObject value){if(!access("avatar.nodes"))return;for(String key:new String[]{"layers","nodes","frameGraph"})try{if(value.has(key))draft.document.put(key,value.opt(key));else draft.document.remove(key);}catch(Exception ignored){}draft.dirty=true;if(draft.onChanged!=null)draft.onChanged.run();if(sheet!=null)sheet.dismiss();}
    public void exportCurrent(){export(frame(draft.document));}public void importFrame(){if(busy)return;if(access("profile.import"))pick(IMPORT,"*/*",null);}
    private void export(JSONObject frame){if(busy||!access("profile.export"))return;host.showDialog(new AlertDialog.Builder(host.getParentActivity(),resources).setTitle(t("Экспортировать рамку")).setItems(new String[]{"DevGram (.dgframe)",t("Совместимый архив (.frame)")},(dialog,which)->{if(!valid()||busy)return;try{if(which==0){archiveExport=null;exporting=new JSONObject().put("format","devgram-frame-1").put("document",frame).toString().getBytes(StandardCharsets.UTF_8);pick(EXPORT,"application/json","DevGram-frame.dgframe");}else{JSONObject graph=frame.optJSONObject("frameGraph");if(graph==null||FrameNodeBuild.spec(FrameNodeDoc.parse(graph.toString())).isEmpty()){error();return;}archiveExport=DevGramProfileDocument.copy(frame);exporting=null;pick(EXPORT,"application/zip","DevGram-frame.frame");}}catch(Exception e){error();}}).create());}
    private void pick(int request,String mime,String filename){try{Intent intent=new Intent(request==EXPORT?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE);if(filename!=null)intent.putExtra(Intent.EXTRA_TITLE,filename);host.getParentActivity().startActivityForResult(intent,request);}catch(Exception e){exporting=null;error();}}
    private boolean importAllowed(){return valid()&&DevGramProfilePolicy.allowed(viewer,"profile.import")&&DevGramProfilePolicy.allowed(viewer,"avatar.nodes");}
    public void result(int request,int result,Intent data){
        if(request!=IMPORT&&request!=EXPORT)return;
        if(result!=Activity.RESULT_OK||data==null||data.getData()==null||!valid()){exporting=null;archiveExport=null;return;}
        android.net.Uri uri=data.getData();
        if(request==EXPORT&&access("profile.export")){
            byte[] bytes=exporting;JSONObject archive=archiveExport;exporting=null;archiveExport=null;if(bytes==null&&archive==null)return;busy=true;int version=++generation;
            DevGramNetworkQueue.postRunnable(()->{boolean ok=false;try(OutputStream stream=ApplicationLoader.applicationContext.getContentResolver().openOutputStream(uri)){
                if(valid()&&stream!=null&&DevGramProfilePolicy.allowed(viewer,"profile.export")){
                    if(archive==null)stream.write(bytes);else FrameArchive.write(stream,"DevGram",UserObject.getUserName(UserConfig.getInstance(host.getCurrentAccount()).getCurrentUser()),FrameNodeDoc.parse(archive.getJSONObject("frameGraph").toString()),source->texture(source));ok=true;
                }
            }catch(Exception|OutOfMemoryError ignored){}boolean saved=ok;AndroidUtilities.runOnUIThread(()->{if(!valid()||version!=generation)return;busy=false;if(saved)BulletinFactory.of(host).createSimpleBulletin(R.raw.contact_check,t("Файл сохранён")).show();else error();});});
        }else if(request==IMPORT&&access("profile.import")&&access("avatar.nodes")){
            busy=true;int version=++generation;DevGramNetworkQueue.postRunnable(()->{JSONObject imported=null;FrameArchive.Imported bundle=null;try(BufferedInputStream stream=new BufferedInputStream(ApplicationLoader.applicationContext.getContentResolver().openInputStream(uri))){stream.mark(4);byte[] header=new byte[4];int n=stream.read(header);stream.reset();if(n==4&&header[0]=='P'&&header[1]=='K')bundle=FrameArchive.read(stream);else{JSONObject value=new JSONObject(new String(FrameArchive.bounded(stream,1048576),StandardCharsets.UTF_8));if(!value.optString("format").equals("devgram-frame-1")&&!value.optString("format").equals("devgram-profile-1"))throw new IOException();if(value.optJSONObject("document")==null)throw new IOException();imported=frame(value.optJSONObject("document"));}}catch(Exception|OutOfMemoryError ignored){}JSONObject document=imported;FrameArchive.Imported archive=bundle;AndroidUtilities.runOnUIThread(()->{if(!importAllowed()||version!=generation){busy=false;return;}if(document==null&&archive==null){busy=false;error();return;}if(archive!=null){busy=false;DevGramFrameFileSheet.show(host,archive,value->{if(importAllowed()&&version==generation)apply(frame(value));});}else validateImport(document,version);});});
        }
    }
    private byte[] texture(String source)throws Exception{
        if(!valid()||!DevGramProfilePolicy.allowed(viewer,"profile.export")||!source.matches("asset:[a-f0-9]{64}\\.(png|jpg|gif|webp)"))throw new IOException();
        String url=DevGramProfileTextures.imageUrl(source),extension=source.substring(source.lastIndexOf('.')+1);File cached=ImageLoader.getHttpFilePath(url,extension);
        if(cached.isFile())try(InputStream input=new FileInputStream(cached)){return FrameArchive.bounded(input,FrameArchive.TEXTURE);}
        java.net.HttpURLConnection connection=(java.net.HttpURLConnection)new java.net.URL(url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(12000);connection.setReadTimeout(20000);
        try{if(connection.getResponseCode()!=200)throw new IOException();try(InputStream input=connection.getInputStream()){return FrameArchive.bounded(input,FrameArchive.TEXTURE);}}finally{connection.disconnect();}
    }
    private void validateImport(JSONObject imported,int version){
        if(!importAllowed()||version!=generation){busy=false;return;}JSONArray textures=DevGramProfileTextures.sources(imported);
        Runnable validate=()->DevGramProfilePolicy.request(host.getCurrentAccount(),"studio/validate",DevGramStudioActivity.json("document",imported),(value,failure)->{if(!valid()||version!=generation)return;busy=false;if(value!=null&&importAllowed())apply(frame(value.optJSONObject("document")));else error();});
        if(textures.length()==0)validate.run();else DevGramProfilePolicy.request(host.getCurrentAccount(),"studio/textures/import",DevGramStudioActivity.json("sources",textures),(value,failure)->{if(!valid()||version!=generation)return;if(value!=null&&importAllowed())validate.run();else{busy=false;error();}});
    }
    private void releasePreviews(){for(DevGramStudioPreview preview:previews)preview.release();previews.clear();}
    public void close(){closed=true;generation++;AndroidUtilities.cancelRunOnUIThread(searchLater);DevGramProfilePolicy.unlisten(policy);releasePreviews();exporting=null;archiveExport=null;if(sheet!=null)sheet.dismiss();}
}
